}
    function initDoctorBarChart() { new ApexCharts(document.querySelector("#doctorBarChart"), { series: [{ name: 'Completed', data: [198, 156, 129, 172, 183] }, { name: 'Canceled', data: [32, 21, 24, 19, 29] }, { name: 'No-Shows', data: [15, 10, 10, 10, 12] }], chart: { type: 'bar', height: 350, stacked: true, redrawOnWindowResize: true }, xaxis: { categories: ['Dr. Ssemwogerere', 'Dr. Johnson', 'Dr. Wamala', 'Dr. Byaruhanga', 'Dr. Sentongo'] }, colors: ['#22c55e', '#ef4444', '#f59e0b'], plotOptions: { bar: { borderRadius: 8 } } }).render(); }
    function initServiceTrendsChart() { new ApexCharts(document.querySelector("#serviceTrendsChart"), { series: [{ name: 'General Checkup', data: [45, 52, 60, 68, 72, 65] }, { name: 'Cardiology', data: [28, 32, 35, 38, 42, 40] }, { name: 'Pediatrics', data: [32, 35, 38, 42, 45, 40] }], chart: { type: 'line', height: 350, redrawOnWindowResize: true }, xaxis: { categories: ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun'] }, colors: ['#6366f1', '#ec4899', '#06b6d4'] }).render(); }

    function renderTables() {
        let filtered = appointments.filter(a => {
            if (departmentFilter !== 'all' && a.department !== departmentFilter) return false;
            if (doctorFilter !== 'all' && a.doctor !== doctorFilter) return false;
            if (dateRange.start && dateRange.end) { if (a.date < dateRange.start || a.date > dateRange.end) return false; }
            return true;
        });
        const search = document.getElementById('recentSearch')?.value.toLowerCase() || '';
        if (search) filtered = filtered.filter(a => a.patient.toLowerCase().includes(search) || a.doctor.toLowerCase().includes(search));
        document.getElementById('recentTableBody').innerHTML = filtered.map(a => `<tr class="border-b  hover:bg-accent hover:text-accent-foreground h-10"><td class="p-4 font-medium">${a.patient}</td><td class="p-4">${a.doctor}</td><td class="p-4">${a.date} ${a.time}</td><td class="p-4">${a.service}</td><td class="p-4"><span class="inline-flex rounded-full px-2 py-0.5 text-xs font-semibold ${a.status === 'Completed' ? 'bg-green-100 text-green-800' : a.status === 'Canceled' ? 'bg-red-100 text-red-800' : 'bg-blue-100 text-blue-800'}">${a.status}</span></td></tr>`).join('') || '<tr><td colspan="5" class="p-8 text-center text-gray-500">No appointments found</td></tr>';
        
        let filteredDocs = doctorStats.filter(d => { if (departmentFilter !== 'all' && d.department !== departmentFilter) return false; if (doctorFilter !== 'all' && d.doctor !== doctorFilter) return false; return true; });
        const docSearch = document.getElementById('doctorSearch')?.value.toLowerCase() || '';
        if (docSearch) filteredDocs = filteredDocs.filter(d => d.doctor.toLowerCase().includes(docSearch));
        document.getElementById('doctorTableBody').innerHTML = filteredDocs.map(d => `<tr class="border-b  hover:bg-accent hover:text-accent-foreground h-10"><td class="p-4 font-medium">${d.doctor}</td><td class="p-4">${d.department}</td><td class="p-4 text-right">${d.total}</td><td class="p-4 text-right">${d.completed}</td><td class="p-4 text-right">${d.canceled}</td><td class="p-4 text-right">${d.noshow}</td><td class="p-4 text-right"><div class="flex items-center justify-end gap-2"><span>${d.rate}%</span><svg class="h-4 w-4 ${d.rate > 80 ? 'text-green-500' : 'text-red-500'}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="${d.rate > 80 ? 'm5 12 7-7 7 7M12 19V5' : 'M12 5v14M19 12l-7 7-7-7'}"/></svg></div></td></tr>`).join('') || '<tr><td colspan="7" class="p-8 text-center text-gray-500">No doctors found</td></tr>';
        
        let filteredServices = serviceStats.filter(s => { if (departmentFilter !== 'all' && s.department !== departmentFilter) return false; return true; });
        const svcSearch = document.getElementById('serviceSearch')?.value.toLowerCase() || '';
        if (svcSearch) filteredServices = filteredServices.filter(s => s.service.toLowerCase().includes(svcSearch));
        document.getElementById('serviceTableBody').innerHTML = filteredServices.map(s => `<tr class="border-b  hover:bg-accent hover:text-accent-foreground h-10"><td class="p-4 font-medium">${s.service}</td><td class="p-4">${s.department}</td><td class="p-4 text-right">${s.appointments}</td><td class="p-4 text-right">${s.duration}</td><td class="p-4 text-right"><div class="flex items-center justify-end gap-2"><span class="${s.trendUp ? 'text-green-500' : 'text-red-500'}">${s.trend}</span><svg class="h-4 w-4 ${s.trendUp ? 'text-green-500' : 'text-red-500'}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="${s.trendUp ? 'm5 12 7-7 7 7M12 19V5' : 'M12 5v14M19 12l-7 7-7-7'}"/></svg></div></td></tr>`).join('') || '<tr><td colspan="5" class="p-8 text-center text-gray-500">No services found</td></tr>';
    }

    // Date Range Picker
    const dateBtn = document.getElementById('dateRangeBtn'), datePicker = document.getElementById('datePickerPopover');
    dateBtn?.addEventListener('click', (e) => { e.stopPropagation(); datePicker.classList.toggle('hidden'); });
    document.getElementById('applyDateBtn')?.addEventListener('click', () => { const start = document.getElementById('startDate').value, end = document.getElementById('endDate').value; if(start && end) { dateRange = { start, end }; document.getElementById('dateRangeText').textContent = `${new Date(start).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })} - ${new Date(end).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}`; datePicker.classList.add('hidden'); renderTables(); showToast('Date range applied'); } });
    document.getElementById('cancelDateBtn')?.addEventListener('click', () => datePicker.classList.add('hidden'));
    document.addEventListener('click', (e) => { if (!dateBtn?.contains(e.target) && !datePicker?.contains(e.target)) datePicker?.classList.add('hidden'); });

    // Filter Dropdowns
    function initFilter(btnId, dropdownId, textId, setter) {
        const btn = document.getElementById(btnId), dropdown = document.getElementById(dropdownId), text = document.getElementById(textId);
        if(!btn) return;
        btn.addEventListener('click', (e) => { e.stopPropagation(); dropdown.classList.toggle('hidden'); });
        dropdown.querySelectorAll('.select-item').forEach(item => { item.addEventListener('click', () => { text.textContent = item.textContent; const val = item.dataset.value; if(setter === 'dept') departmentFilter = val; else doctorFilter = val; dropdown.classList.add('hidden'); renderTables(); }); });
        document.addEventListener('click', (e) => { if(!btn.contains(e.target) && !dropdown.contains(e.target)) dropdown.classList.add('hidden'); });
    }
    initFilter('deptFilterBtn', 'deptFilterDropdown', 'deptFilterText', 'dept');
    initFilter('doctorFilterBtn', 'doctorFilterDropdown', 'doctorFilterText', 'doctor');

    // Tab switching
    function activateTab(tabId) { ['overview', 'trends', 'bydoctor', 'byservice'].forEach(t => { const panel = document.getElementById(`tab-${t}`); const btn = document.querySelector(`.tab-btn[data-tab="${t}"]`); if(panel) panel.setAttribute('data-state', t === tabId ? 'active' : 'inactive'); if(btn) { if(t === tabId) btn.classList.add('active'); else btn.classList.remove('active'); } }); }
    document.querySelectorAll('.tab-btn').forEach(btn => btn.addEventListener('click', () => activateTab(btn.dataset.tab)));

    // Refresh, Export, Search
    document.getElementById('refreshBtn')?.addEventListener('click', () => { renderTables(); showToast('Data refreshed'); });
    document.getElementById('exportBtn')?.addEventListener('click', () => { let data = appointments; if(departmentFilter !== 'all') data = data.filter(a => a.department === departmentFilter); if(doctorFilter !== 'all') data = data.filter(a => a.doctor === doctorFilter); const headers = ['Patient', 'Doctor', 'Date', 'Time', 'Service', 'Status', 'Department']; const rows = data.map(a => [a.patient, a.doctor, a.date, a.time, a.service, a.status, a.department]); const csv = [headers.join(','), ...rows.map(row => row.map(c => `"${c}"`).join(','))].join('\n'); const blob = new Blob([csv], { type: 'text/csv' }); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = `appointment_reports_${new Date().toISOString().slice(0,10)}.csv`; a.click(); URL.revokeObjectURL(a.href); showToast('Export complete'); });
    document.getElementById('recentSearch')?.addEventListener('input', renderTables);
    document.getElementById('doctorSearch')?.addEventListener('input', renderTables);
    document.getElementById('serviceSearch')?.addEventListener('input', renderTables);


    // Initialize
    initPieChart(); initBarChart(); initTrendsChart(); initDoctorBarChart(); initServiceTrendsChart(); initTrendsChart();
initWeeklyChart();
initHourlyChart();
    renderTables();
    activateTab('overview');

    function refreshAllCharts() {
        setTimeout(() => { window.dispatchEvent(new Event('resize')); }, 350);
    }
    document.querySelector('.lucide-menu')?.closest('button')?.addEventListener('click', refreshAllCharts);
</script>

    
    


